import os
import shutil
import cv2
import numpy as np
from pathlib import Path
from src.reporting.generator import ReportGenerator
from src.reporting.pipeline import ReportingPipeline

# Setup paths
output_dir = Path("reproduction_output")
if output_dir.exists():
    shutil.rmtree(output_dir)
output_dir.mkdir()

# Create dummy image in memory
dummy_img = np.zeros((100, 100, 3), dtype=np.uint8)
cv2.rectangle(dummy_img, (20, 20), (80, 80), (0, 255, 0), -1)

# Mock Data
analysis_results = {
    'matched_pixels': 100,
    'total_pixels': 200,
    'percentage': 50.0,
    'original_image': dummy_img.copy(),
    'image_with_contours': dummy_img.copy(),
}

metadata = {
    'part_number': 'TEST-DB-REHYDRATION',
    'author': 'Tester',
}

# Mock Report Context (Simulating what comes from DB)
report_context = {
    "image_pipeline": [
        {
            "title": "1. Sym: Vertical Reflection", 
            "path": "dummy_path.png", 
            "image": dummy_img.copy() # Rehydrated image
        }
    ],
    "symmetry_results": {
        "vertical_reflection": {"score": 0.99},
        "visualizations": [
            {
                "title": "Vertical Reflection", # Title from SymmetryAnalyzer
                "path": "dummy_path.png"     # Old path
            }
        ]
    }
}

print("Running manual rehydration logic verification...")

# --- SIMULATE LOGIC ADDED TO PIPELINE.PY ---
sym_results = report_context["symmetry_results"]
image_pipeline = report_context.get("image_pipeline", [])

for vis in sym_results["visualizations"]:
    vis_title = vis.get("title", "")
    matching_step = next(
        (step for step in image_pipeline 
            if step.get("title", "").endswith(vis_title) and step.get("image") is not None), 
        None
    )

    if matching_step:
        print(f"Match found for '{vis_title}' -> '{matching_step['title']}'")
        vis["image"] = matching_step["image"]
    else:
        print(f"No match found for '{vis_title}'")

# --- GENERATE REPORT ---
print("Generating PDF...")
generator = ReportGenerator(project_name="Reproduction", output_dir=str(output_dir))
pdf_path = generator.generate_report(analysis_results, metadata, debug_data=report_context)

if pdf_path:
    print(f"PDF successfully generated at: {pdf_path}")
else:
    print("PDF generation failed.")

