import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Layers, Play, Trash2, Plus, CheckCircle, AlertCircle, Image as ImageIcon } from 'lucide-react';
import axios from 'axios';

// API Base
const API_BASE = import.meta.env.VITE_API_BASE_URL || '/api';

export function BatchAnalysisView() {
  const [selectedProject, setSelectedProject] = useState<string>('');
  const [queue, setQueue] = useState<{ file: File; status: 'pending' | 'processing' | 'done' | 'error'; result?: any }[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  // Fetch Projects
  const { data: projects } = useQuery({
    queryKey: ['projects'],
    queryFn: async () => {
      const res = await axios.get(`${API_BASE}/projects`);
      return res.data;
    }
  });

  const handleFiles = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files).map(file => ({
        file,
        status: 'pending' as const
      }));
      setQueue(prev => [...prev, ...newFiles]);
    }
  };

  const removeFromQueue = (index: number) => {
    setQueue(prev => prev.filter((_, i) => i !== index));
  };

  const runBatch = async () => {
    if (!selectedProject || queue.length === 0) return;

    setIsProcessing(true);

    // Process sequentially
    for (let i = 0; i < queue.length; i++) {
      if (queue[i].status === 'done') continue;

      setQueue(prev => prev.map((item, idx) => idx === i ? { ...item, status: 'processing' } : item));

      const formData = new FormData();
      formData.append('project', selectedProject);
      formData.append('image', queue[i].file);
      formData.append('debug', 'false'); // Force no-debug for batch speed
      formData.append('skip_report_generation', 'true'); // Important for speed

      // Add other defaults matching the server expectations
      formData.append('color_alignment', 'true');
      formData.append('alignment', 'true');
      formData.append('object_alignment', 'true');
      formData.append('apply_mask', 'true');
      formData.append('symmetry', 'true');
      formData.append('aggregate', 'true');
      formData.append('blur', 'true');

      // Note: The current server analyze_image endpoint doesn't accept a custom checker file via upload for single run 
      // EXCEPT via standard config or if we extended it. 
      // The `args` in server.py says `sample_color_checker=None`. 
      // The endpoint `analyze_image` does NOT currently accept `sample_color_checker` as a file upload.
      // It only accepts `project`, `image` etc.
      // So the checker feature in Batch view might be limited unless we update the server.
      // However, for now, let's just proceed with the image analysis.

      try {
        const res = await axios.post(`${API_BASE}/analyze`, formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });

        setQueue(prev => prev.map((item, idx) => idx === i ? { ...item, status: 'done', result: res.data } : item));
      } catch (error) {
        console.error(error);
        setQueue(prev => prev.map((item, idx) => idx === i ? { ...item, status: 'error' } : item));
      }
    }

    setIsProcessing(false);
  };

  return (
    <div className="flex h-[calc(100vh-8rem)] gap-6">
      {/* Controls */}
      <div className="w-1/3 flex flex-col gap-6">
        <div className="p-6 bg-neutral-900 border border-neutral-800 rounded-xl space-y-6">
          <div className="flex items-center gap-3 text-green-500 mb-2">
            <Layers className="w-5 h-5" />
            <h2 className="text-lg font-bold">Batch Configuration</h2>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-neutral-400">Target Project</label>
            <select 
              value={selectedProject}
              onChange={(e) => setSelectedProject(e.target.value)}
              className="w-full bg-neutral-950 border border-neutral-700 rounded-lg px-3 py-2 text-sm focus:border-green-600 outline-none"
            >
              <option value="">Select Project...</option>
              {projects?.map((p: any) => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-neutral-400">Add Images</label>
            <label className="flex items-center justify-center w-full h-32 px-4 transition bg-neutral-950 border-2 border-neutral-800 border-dashed rounded-lg appearance-none cursor-pointer hover:border-green-600/50 focus:outline-none">
              <div className="flex flex-col items-center space-y-2">
                <Plus className="w-8 h-8 text-neutral-500" />
                <span className="font-medium text-neutral-500">Drop files or Click</span>
              </div>
              <input type="file" multiple accept="image/*" className="hidden" onChange={handleFiles} />
            </label>
          </div>

          {/* Checker Upload (Visual only for now until backend support) */}
          <div className="space-y-2 opacity-50 cursor-not-allowed" title="Custom checker upload for batch requires backend update">
             <label className="text-sm font-medium text-neutral-400">Batch Color Checker (Optional)</label>
             <input type="file" disabled accept="image/*" className="w-full text-sm text-neutral-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-semibold file:bg-neutral-800 file:text-green-500 hover:file:bg-neutral-700"/>
          </div>

          <button
            onClick={runBatch}
            disabled={isProcessing || !selectedProject || queue.length === 0}
            className={`w-full flex items-center justify-center gap-2 py-3 rounded-lg font-bold transition-all ${
              isProcessing 
                ? 'bg-neutral-800 text-neutral-500 cursor-wait'
                : 'bg-green-600 hover:bg-green-500 text-white shadow-lg shadow-green-900/20'
            }`}
          >
            {isProcessing ? (
              <>Processing...</>
            ) : (
              <>
                <Play className="w-4 h-4" />
                Run Batch Analysis
              </>
            )}
          </button>
        </div>
      </div>

      {/* Queue */}
      <div className="flex-1 bg-neutral-900 border border-neutral-800 rounded-xl overflow-hidden flex flex-col">
        <div className="p-4 border-b border-neutral-800 bg-neutral-900/50 backdrop-blur flex justify-between items-center">
          <h3 className="font-medium text-neutral-300">Processing Queue ({queue.length})</h3>
          <button onClick={() => setQueue([])} className="text-xs text-red-500 hover:text-red-400">Clear All</button>
        </div>

        <div className="flex-1 overflow-y-auto p-2 space-y-2">
          {queue.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-neutral-600 gap-4">
              <Layers className="w-12 h-12 opacity-20" />
              <p>Queue is empty</p>
            </div>
          )}

          {queue.map((item, idx) => (
            <div key={idx} className="flex items-center gap-4 p-3 bg-neutral-950 rounded-lg border border-neutral-800">
              <div className="w-10 h-10 bg-neutral-900 rounded flex items-center justify-center text-neutral-600">
                <ImageIcon className="w-5 h-5" />
              </div>

              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium truncate text-neutral-300">{item.file.name}</p>
                <p className="text-xs text-neutral-500">{(item.file.size / 1024 / 1024).toFixed(2)} MB</p>
              </div>

              <div className="flex items-center gap-4">
                {item.status === 'pending' && <span className="text-xs text-neutral-500 bg-neutral-900 px-2 py-1 rounded">Pending</span>}
                {item.status === 'processing' && <span className="text-xs text-blue-400 bg-blue-400/10 px-2 py-1 rounded animate-pulse">Processing...</span>}
                {item.status === 'done' && (
                  <div className="flex items-center gap-2 text-green-500">
                    <span className="text-xs bg-green-500/10 px-2 py-1 rounded">Done</span>
                    <CheckCircle className="w-4 h-4" />
                  </div>
                )}
                {item.status === 'error' && (
                  <div className="flex items-center gap-2 text-red-500">
                    <span className="text-xs bg-red-500/10 px-2 py-1 rounded">Failed</span>
                    <AlertCircle className="w-4 h-4" />
                  </div>
                )}

                <button 
                  onClick={() => removeFromQueue(idx)}
                  disabled={item.status === 'processing'}
                  className="p-2 hover:bg-neutral-800 rounded-full text-neutral-500 hover:text-red-400 transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

